package cn.iocoder.yudao.module.zsjos.service.gift;
import cn.iocoder.yudao.module.zsjos.controller.admin.gift.vo.*; import cn.iocoder.yudao.module.zsjos.dal.dataobject.gift.*; import cn.iocoder.yudao.module.zsjos.dal.mysql.gift.*; import com.baomidou.mybatisplus.core.toolkit.Wrappers; import jakarta.annotation.Resource; import org.springframework.stereotype.Service; import java.util.*;
@Service public class GiftConfigServiceImpl implements GiftConfigService { @Resource GiftConfigMapper m; public Long create(GiftConfigSaveReqVO r){ validate(r,null); GiftConfigDO d=new GiftConfigDO(); d.setParentId(r.getParentId()==null?0:r.getParentId());d.setName(r.getName());d.setCode(r.getCode());d.setStatus(r.getStatus());d.setSort(r.getSort());m.insert(d);return d.getId(); } public void update(GiftConfigSaveReqVO r){ validate(r,r.getId()); GiftConfigDO d=new GiftConfigDO();d.setId(r.getId());d.setParentId(r.getParentId()==null?0:r.getParentId());d.setName(r.getName());d.setCode(r.getCode());d.setStatus(r.getStatus());d.setSort(r.getSort());m.updateById(d);} public void delete(Long id){ if(m.selectCount(Wrappers.lambdaQuery(GiftConfigDO.class).eq(GiftConfigDO::getParentId,id))>0) throw new IllegalArgumentException("礼品节点存在子节点"); m.deleteById(id);} public List<GiftConfigDO> list(Integer s){ List<GiftConfigDO> all=m.selectList(Wrappers.lambdaQuery(GiftConfigDO.class).eq(s!=null,GiftConfigDO::getStatus,s).orderByAsc(GiftConfigDO::getSort)); Map<Long,GiftConfigDO> byId=new LinkedHashMap<>(); for(GiftConfigDO d:all){byId.put(d.getId(),d);} List<GiftConfigDO> roots=new ArrayList<>(); for(GiftConfigDO d:all){ GiftConfigDO parent=d.getParentId()==null?null:byId.get(d.getParentId()); if(parent!=null){ if(parent.getChildren()==null)parent.setChildren(new ArrayList<>()); parent.getChildren().add(d);} else { roots.add(d);} } return roots; } private void validate(GiftConfigSaveReqVO r,Long id){ if(r.getParentId()!=null&&r.getParentId()>0&&m.selectById(r.getParentId())==null) throw new IllegalArgumentException("父节点不存在"); if(id!=null&&Objects.equals(id,r.getParentId())) throw new IllegalArgumentException("不能循环引用"); if(m.selectCount(Wrappers.lambdaQuery(GiftConfigDO.class).eq(GiftConfigDO::getCode,r.getCode()).ne(id!=null,GiftConfigDO::getId,id))>0) throw new IllegalArgumentException("编码已存在"); }}
